/* Clubhouse: local-first relationship activity tracker. Demo data is stored in this browser. */
const LEAGUES={NFL:['Arizona Cardinals','Atlanta Falcons','Baltimore Ravens','Buffalo Bills','Carolina Panthers','Chicago Bears','Cincinnati Bengals','Cleveland Browns','Dallas Cowboys','Denver Broncos','Detroit Lions','Green Bay Packers','Houston Texans','Indianapolis Colts','Jacksonville Jaguars','Kansas City Chiefs','Las Vegas Raiders','Los Angeles Chargers','Los Angeles Rams','Miami Dolphins','Minnesota Vikings','New England Patriots','New Orleans Saints','New York Giants','New York Jets','Philadelphia Eagles','Pittsburgh Steelers','San Francisco 49ers','Seattle Seahawks','Tampa Bay Buccaneers','Tennessee Titans','Washington Commanders'],MLB:['Arizona Diamondbacks','Atlanta Braves','Baltimore Orioles','Boston Red Sox','Chicago Cubs','Chicago White Sox','Cincinnati Reds','Cleveland Guardians','Colorado Rockies','Detroit Tigers','Houston Astros','Kansas City Royals','Los Angeles Angels','Los Angeles Dodgers','Miami Marlins','Milwaukee Brewers','Minnesota Twins','New York Mets','New York Yankees','Athletics','Philadelphia Phillies','Pittsburgh Pirates','San Diego Padres','San Francisco Giants','Seattle Mariners','St. Louis Cardinals','Tampa Bay Rays','Texas Rangers','Toronto Blue Jays','Washington Nationals'],MLS:['Atlanta United','Austin FC','Charlotte FC','Chicago Fire FC','FC Cincinnati','Colorado Rapids','Columbus Crew','D.C. United','FC Dallas','Houston Dynamo FC','Inter Miami CF','LA Galaxy','Los Angeles Football Club','Minnesota United FC','CF Montréal','Nashville SC','New England Revolution','New York City FC','New York Red Bulls','Orlando City SC','Philadelphia Union','Portland Timbers','Real Salt Lake','San Diego FC','San Jose Earthquakes','Seattle Sounders FC','Sporting Kansas City','St. Louis CITY SC','Toronto FC','Vancouver Whitecaps FC'],NHL:['Anaheim Ducks','Boston Bruins','Buffalo Sabres','Calgary Flames','Carolina Hurricanes','Chicago Blackhawks','Colorado Avalanche','Columbus Blue Jackets','Dallas Stars','Detroit Red Wings','Edmonton Oilers','Florida Panthers','Los Angeles Kings','Minnesota Wild','Montréal Canadiens','Nashville Predators','New Jersey Devils','New York Islanders','New York Rangers','Ottawa Senators','Philadelphia Flyers','Pittsburgh Penguins','San Jose Sharks','Seattle Kraken','St. Louis Blues','Tampa Bay Lightning','Toronto Maple Leafs','Utah Mammoth','Vancouver Canucks','Vegas Golden Knights','Washington Capitals','Winnipeg Jets'],NBA:['Atlanta Hawks','Boston Celtics','Brooklyn Nets','Charlotte Hornets','Chicago Bulls','Cleveland Cavaliers','Dallas Mavericks','Denver Nuggets','Detroit Pistons','Golden State Warriors','Houston Rockets','Indiana Pacers','LA Clippers','Los Angeles Lakers','Memphis Grizzlies','Miami Heat','Milwaukee Bucks','Minnesota Timberwolves','New Orleans Pelicans','New York Knicks','Oklahoma City Thunder','Orlando Magic','Philadelphia 76ers','Phoenix Suns','Portland Trail Blazers','Sacramento Kings','San Antonio Spurs','Toronto Raptors','Utah Jazz','Washington Wizards']};
const CAPS=['Marketing in a Box','Finance in a Box','Ticket Sales Accelerator','Collections Accelerator','Other'];
const NEXT_STEP_TYPES=['Meeting scheduled','Materials to be shared','NDA in progress','SOW in progress','Awaiting their response','Yet to be decided'];
const SEED_USERS=[{id:'u-admin',name:'Jordan Lee',role:'Admin',title:'SVP · Admin'},{id:'u-avery',name:'Avery Morgan',role:'User',title:'Senior Advisor'},{id:'u-jamie',name:'Jamie Chen',role:'User',title:'Advisor'},{id:'u-taylor',name:'Taylor Brooks',role:'User',title:'Internal POC'}];
const dt=(offset=0)=>{const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()+offset);return d.toISOString().slice(0,10)};
function freshDB(){
 const clubs=[];Object.entries(LEAGUES).forEach(([league,names])=>names.forEach((name,i)=>clubs.push({id:`${league}-${i+1}`,league,name})));
 const ids=Object.fromEntries(clubs.map(c=>[c.name,c.id]));
 const interactions=[
  {id:'i-1',clubId:ids['New York Yankees'],date:dt(-2),stakeholders:[{name:'Morgan Ellis',role:'VP, Partnerships'},{name:'Chris Patel',role:'Director, Marketing'}],participants:[{name:'Avery Morgan',role:'Advisor'},{name:'Taylor Brooks',role:'Internal POC'}],summary:'Discussed improving sponsor renewal workflows and how a more consistent sales motion could support the upcoming planning cycle. Team is interested in seeing examples from comparable clubs.',capabilities:['Marketing in a Box','Ticket Sales Accelerator'],other:'',owner:'u-avery',sample:true,followups:[{id:'f-1',description:'Share the sponsorship activation overview and two relevant case studies',owner:'u-avery',due:dt(2),status:'Open'},{id:'f-2',description:'Introduce the club team to the ticketing solutions lead',owner:'u-taylor',due:dt(-1),status:'Open'}]},
  {id:'i-2',clubId:ids['New York Yankees'],date:dt(-20),stakeholders:[{name:'Morgan Ellis',role:'VP, Partnerships'}],participants:[{name:'Avery Morgan',role:'Advisor'}],summary:'Initial conversation about commercial priorities, current partner servicing process, and areas where the club would welcome practical examples.',capabilities:['Finance in a Box'],other:'',owner:'u-avery',sample:true,followups:[{id:'f-3',description:'Send a short overview of finance capabilities',owner:'u-avery',due:dt(-15),status:'Done'}]},
  {id:'i-3',clubId:ids['Boston Celtics'],date:dt(-5),stakeholders:[{name:'Jordan Kim',role:'Chief Revenue Officer'}],participants:[{name:'Jamie Chen',role:'Advisor'}],summary:'Explored approaches to increase ticket sales conversion and improve coordination between marketing and sales teams before the next homestand.',capabilities:['Ticket Sales Accelerator','Other'],other:'Fan engagement journey mapping',owner:'u-jamie',sample:true,followups:[{id:'f-4',description:'Prepare a working session with ticket sales leadership',owner:'u-jamie',due:dt(4),status:'Open'}]},
  {id:'i-4',clubId:ids['Seattle Sounders FC'],date:dt(-11),stakeholders:[{name:'Alex Rivera',role:'VP, Business Operations'}],participants:[{name:'Taylor Brooks',role:'Internal POC'}],summary:'Reviewed collections process challenges and shared a high-level view of the collections accelerator. Club requested a next step focused on implementation considerations.',capabilities:['Collections Accelerator'],other:'',owner:'u-taylor',sample:true,followups:[{id:'f-5',description:'Send next step materials on collections process',owner:'u-taylor',due:dt(-3),status:'Open'}]},
  {id:'i-5',clubId:ids['Dallas Cowboys'],date:dt(-1),stakeholders:[{name:'Sam Carter',role:'SVP, Partnerships'}],participants:[{name:'Avery Morgan',role:'Advisor'},{name:'Jamie Chen',role:'Advisor'}],summary:'Followed up on earlier discussion and aligned on a discovery session with the partnership operations team. Club wants to understand what a first phase could look like.',capabilities:['Marketing in a Box','Finance in a Box'],other:'',owner:'u-avery',sample:true,followups:[{id:'f-6',description:'Coordinate discovery session with partnership operations',owner:'u-avery',due:dt(5),status:'Open'}]}
 ];
 interactions.forEach((i,n)=>{if(!i.nextStepType)i.nextStepType=NEXT_STEP_TYPES[n%NEXT_STEP_TYPES.length]});
 const meetings=[{id:'m-1',clubId:ids['New York Yankees'],date:dt(3),participants:['Morgan Ellis','Avery Morgan'],agenda:'Review activation examples and agree on next steps',owner:'u-avery',status:'Planned'},{id:'m-2',clubId:ids['Boston Celtics'],date:dt(6),participants:['Jordan Kim','Jamie Chen'],agenda:'Ticket sales working session',owner:'u-jamie',status:'Planned'},{id:'m-3',clubId:ids['Seattle Sounders FC'],date:dt(10),participants:['Alex Rivera','Taylor Brooks'],agenda:'Collections accelerator next step',owner:'u-taylor',status:'Planned'}];
 return {users:SEED_USERS,clubs,interactions,meetings,activeUser:'u-admin',seeded:true};
}
const STORE='clubhouse_v1';let db;try{db=JSON.parse(localStorage.getItem(STORE))||freshDB()}catch(e){db=freshDB()};
function save(){localStorage.setItem(STORE,JSON.stringify(db));fetch('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({state:db})}).then(async r=>{if(!r.ok){const e=await r.json();toast(e.error||'Could not save to the local server')}}).catch(()=>{})}const user=()=>db.users.find(u=>u.id===db.activeUser)||db.users[0];const isAdmin=()=>user().role==='Admin';const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let page='home',selectedClub=null,clubTab='history',toastTimer,editingMeeting=null,editingInteraction=null,meetingToComplete=null,activeDigestItems=[];
const clubBy=id=>db.clubs.find(c=>c.id===id);const who=id=>db.users.find(u=>u.id===id)?.name||'Unassigned';
function exlPoc(i){if(i.exlPoc)return i.exlPoc;const p=(i.participants||[]).find(x=>(x.role||'').toLowerCase().includes('poc'))||(i.participants||[])[0];return p?.name||who(i.owner)}
function clubPoc(i){return i.clubPoc||(i.stakeholders||[])[0]?.name||'Not recorded'}
function clubPocDesignation(i){return i.clubPocDesignation||(i.stakeholders||[])[0]?.role||'Designation not recorded'}
function contactMeta(i){return 'EXL POC: '+esc(exlPoc(i))+' · Club/client POC: '+esc(clubPoc(i))+' — '+esc(clubPocDesignation(i))}
function nextStepPill(i){const tag=i.nextStepType||'Yet to be decided';const n=Math.max(0,NEXT_STEP_TYPES.indexOf(tag));return '<span class="next-step-tag next-tag-'+n+'">'+esc(tag)+'</span>'}
const initials=n=>n.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();const visibleClubs=()=>db.clubs;const canSeeClub=id=>!!clubBy(id);const visibleInteractions=()=>db.interactions;const visibleMeetings=()=>db.meetings.filter(m=>m.status==='Planned');const allFollowups=()=>visibleInteractions().flatMap(i=>i.followups.map(f=>({...f,interaction:i,club:clubBy(i.clubId)}))).filter(f=>isAdmin()||f.owner===user().id||f.interaction.owner===user().id);
function fmt(d,opts={month:'short',day:'numeric',year:'numeric'}){if(!d)return '—';return new Date(`${d}T12:00:00`).toLocaleDateString('en-US',opts)}function relative(d){const delta=Math.round((new Date(d+'T12:00:00')-new Date(dt()+'T12:00:00'))/86400000);return delta<0?`${Math.abs(delta)}d overdue`:delta===0?'Due today':delta===1?'Due tomorrow':`Due in ${delta}d`}
function toast(msg){const el=document.createElement('div');el.className='toast';el.textContent=msg;document.body.append(el);setTimeout(()=>el.remove(),2800)}
function icon(name){return ({home:'◫',clubs:'▦',log:'＋',followups:'✓',digest:'◷',admin:'⚙'})[name]||'•'}
function app(){const u=user();document.getElementById('app').innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">C</div><div><div class="brand-name">clubhouse</div><div class="brand-sub">Relationship activity</div></div></div><div class="nav-label">Workspace</div><nav class="nav">${[['home','Overview'],['clubs','Club directory'],...(isAdmin()?[]:[['log','Log interaction']]),['followups','My next steps']].map(([id,label])=>`<button class="${(page===id||(id==='home'&&page==='digest'))?'active':''}" data-page="${id}"><span class="nav-icon">${icon(id)}</span><span>${label}</span></button>`).join('')}${isAdmin()?`<div class="nav-divider"></div><div class="nav-label">Administration</div><button class="${page==='admin'?'active':''}" data-page="admin"><span class="nav-icon">${icon('admin')}</span><span>Workspace users</span></button>`:''}</nav><div class="sidebar-bottom"><div class="demo-badge"><b>Demo workspace</b>Sample activity is labeled. Changes save to this workspace.</div><div class="profile"><div class="avatar">${initials(u.name)}</div><div><div class="profile-name">${esc(u.name)}</div><div class="profile-role">${esc(u.title)}</div></div><button class="signout" id="signout">Sign out</button></div></div></aside><main class="main"><header class="topbar"><div class="crumb">Relationship activity <span style="color:#bbc5bd"> / </span> ${pageLabel()}</div><div class="top-right"><span class="today">${new Date().toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'})}</span><div class="user-small"><div class="avatar">${initials(u.name)}</div>${esc(u.name)}</div></div></header><div class="content" id="view"></div></main></div>`;renderPage();bindShell()}
function pageLabel(){return ({home:'Overview',clubs:'Club directory',log:'Log interaction',followups:'My next steps',digest:'Overview',admin:'Workspace users',club:'Club detail'})[page]||'Overview'}
function bindShell(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page==='digest'?'home':b.dataset.page;selectedClub=null;app()});$('#signout').onclick=async()=>{await fetch('/api/logout',{method:'POST'});loginPage();}}
function head(kicker,title,desc,action=''){return `<div class="page-head"><div><div class="greeting">${kicker}</div><h1 class="page-title">${title}</h1><p class="page-desc">${desc}</p></div>${action?`<div class="head-actions">${action}</div>`:''}</div>`}
function stat(label,note,value,ico){return `<div class="stat-card"><div class="stat-top"><div class="stat-label">${label}</div><div class="stat-icon">${ico}</div></div><div class="stat-num">${value}</div><div class="stat-note">${note}</div></div>`}
function clubShort(c){return c?.name||'Unknown club'}function leagueTag(l){return `<span class="pill blue">${l}</span>`}function capsTags(a,other){return (a||[]).map(c=>`<span class="pill ${c==='Other'?'orange':'green'}">${esc(c==='Other'&&other?`Other · ${other}`:c)}</span>`).join('')}
function renderPage(){const v=$('#view');if(page==='home')v.innerHTML=homePage();else if(page==='clubs')v.innerHTML=clubsPage();else if(page==='club')v.innerHTML=clubPage();else if(page==='log')v.innerHTML=isAdmin()?`${head('ADMIN VIEW','Interaction entry is for regular users','The Admin account reviews and manages activity. Sign in as an advisor or EXL POC to log a conversation.')}`:interactionForm();else if(page==='followups')v.innerHTML=followupsPage();else if(page==='digest')v.innerHTML=digestPage();else if(page==='admin')v.innerHTML=adminPage();bindPage()}
function homePage(){return digestPage()}
function activityRow(i){const c=clubBy(i.clubId);return '<div class="activity-row"><div class="league-mark">'+(c?.league||'—')+'</div><div><div class="activity-club">'+esc(clubShort(c))+' '+(i.sample?'<span class="pill">Sample</span>':'')+'</div><div class="activity-meta">'+fmt(i.date)+' · '+contactMeta(i)+'</div><div class="activity-summary">'+esc(i.summary)+'</div><div class="cap-list">'+capsTags(i.capabilities,i.other)+'</div></div><button class="action-link" data-open-club="'+i.clubId+'">History →</button></div>'}
function meetingCard(m){const c=clubBy(m.clubId);const d=new Date(m.date+'T12:00:00');return `<div class="meeting-item"><div class="date-box"><span class="month">${d.toLocaleDateString('en-US',{month:'short'})}</span><span class="day">${d.getDate()}</span></div><div><div class="meeting-name">${esc(clubShort(c))} <span class="pill blue">${esc(m.meetingType||'Meeting')}</span></div><div class="meeting-info">${esc(m.agenda||'Meeting planned')} · ${esc(m.exlPoc||m.participants?.join(', ')||who(m.owner))}${m.clubPoc?' · Club/client POC: '+esc(m.clubPoc)+(m.clubPocDesignation?' — '+esc(m.clubPocDesignation):''):''}</div></div></div>`}
function taskCard(f){return `<div class="task-item"><span class="task-dot ${f.due<dt()?'overdue':''}"></span><div style="min-width:0"><div class="task-name">${esc(f.description)}</div><div class="task-info">${esc(clubShort(f.club))} · ${relative(f.due)} · ${esc(who(f.owner))}</div></div></div>`}
function clubsPage(){const clubs=visibleClubs();return `${head('CLUB DIRECTORY','Know every relationship','Find a club to review history, upcoming meetings, and follow-through.',isAdmin()?'':'<button class="btn primary" data-page="log">＋ &nbsp; Log interaction</button>')}<div class="card"><div class="card-head"><div><div class="card-title">Professional sports clubs</div><div class="card-sub">${clubs.length} clubs across all five leagues</div></div><div class="filters"><input class="input search" id="club-search" placeholder="Search clubs…"><select class="select" id="league-filter"><option value="all">All leagues</option>${Object.keys(LEAGUES).map(l=>`<option>${l}</option>`).join('')}</select></div></div><div class="club-list" id="club-results">${clubCards(clubs)}</div></div>`}
function clubCards(clubs){return clubs.length?clubs.map(c=>{const n=visibleInteractions().filter(i=>i.clubId===c.id).length;return `<div class="club-card" data-open-club="${c.id}"><div class="club-logo">${c.league}</div><div class="club-main"><div class="club-name">${esc(c.name)}</div><div class="club-meta">${c.league} · Open to all advisors and POCs</div></div><div class="club-count">${n} ${n===1?'interaction':'interactions'} →</div></div>`}).join(''):`<div class="empty">No clubs match your search.</div>`}
function clubOverview(club,interactions,plannedMeetings){
 const exl=new Map(),stakeholders=new Map();
 const add=(map,name,role='')=>{if(!name)return;const key=name.trim().toLowerCase();if(!map.has(key))map.set(key,{name:name.trim(),roles:new Set()});if(role)map.get(key).roles.add(role.trim())};
 interactions.forEach(i=>{const p=(i.participants||[]).find(x=>x.name===i.exlPoc)||(i.participants||[]).find(x=>(x.role||'').toLowerCase().includes('advisor'))||(i.participants||[])[0];add(exl,i.exlPoc||p?.name,p?.role);(i.stakeholders||[]).forEach(x=>add(stakeholders,x.name,x.role));if(!(i.stakeholders||[]).length)add(stakeholders,i.clubPoc,i.clubPocDesignation)});
 plannedMeetings.forEach(m=>{add(exl,m.exlPoc);add(stakeholders,m.clubPoc,m.clubPocDesignation)});
 const dates=[...new Set(interactions.map(i=>i.date).filter(Boolean))].sort((a,b)=>b.localeCompare(a));
 const next=plannedMeetings.filter(m=>m.date>=dt()).sort((a,b)=>a.date.localeCompare(b.date));
 const contactList=items=>items.length?`<div class="club-contact-list">${items.map(({name,roles})=>`<div class="club-contact"><span class="club-contact-avatar">${esc(initials(name))}</span><span><strong>${esc(name)}</strong>${roles.size?`<small>${[...roles].map(esc).join(' · ')}</small>`:''}</span></div>`).join('')}</div>`:'<div class="club-overview-empty">No contacts recorded yet.</div>';
 return `<section class="club-overview"><div class="club-overview-card contacts-card"><div class="club-overview-title"><span class="club-overview-icon">EXL</span><div><strong>EXL points of contact</strong><small>${exl.size} ${exl.size===1?'person':'people'} across recorded meetings</small></div></div>${contactList([...exl.values()])}</div><div class="club-overview-card contacts-card"><div class="club-overview-title"><span class="club-overview-icon light">CLUB</span><div><strong>Club stakeholders</strong><small>${stakeholders.size} ${stakeholders.size===1?'contact':'contacts'} recorded</small></div></div>${contactList([...stakeholders.values()])}</div><div class="club-overview-card dates-card"><div class="club-overview-title"><span class="club-overview-icon orange">◷</span><div><strong>Meeting dates</strong><small>${dates.length} completed ${dates.length===1?'meeting date':'meeting dates'}</small></div></div>${dates.length?`<div class="meeting-date-chips">${dates.map(d=>`<span>${fmt(d)}</span>`).join('')}</div>`:'<div class="club-overview-empty">No completed meetings recorded yet.</div>'}</div><div class="club-overview-card next-meeting-card"><div class="club-overview-title"><span class="club-overview-icon orange">→</span><div><strong>Next meeting</strong><small>Upcoming with this club</small></div></div>${next.length?`<div class="next-meeting-date">${fmt(next[0].date)}</div><div class="next-meeting-caption">${esc(next[0].meetingType||'Planned meeting')}${next[0].agenda?' · '+esc(next[0].agenda):''}</div>${next.length>1?`<span class="meeting-more">+ ${next.length-1} more planned</span>`:''}`:'<div class="club-overview-empty">No upcoming meeting scheduled.</div>'}</div></section>`
}
function clubPage(){const c=clubBy(selectedClub);if(!c||!canSeeClub(c.id)){page='clubs';return clubsPage()}const ix=visibleInteractions().filter(i=>i.clubId===c.id).sort((a,b)=>b.date.localeCompare(a.date));const meetings=visibleMeetings().filter(m=>m.clubId===c.id).sort((a,b)=>a.date.localeCompare(b.date));const fs=allFollowups().filter(f=>f.club?.id===c.id&&f.status==='Open').sort((a,b)=>a.due.localeCompare(b.due));return `${head('CLUB RELATIONSHIP',esc(c.name),`${c.league} · ${ix.length} completed ${ix.length===1?'interaction':'interactions'}`,`<button class="btn" data-page="clubs">← &nbsp; All clubs</button>${isAdmin()?'':`<button class="btn primary" data-log-club="${c.id}">＋ &nbsp; Log interaction</button>`}`)}<div class="card"><div class="club-hero"><div class="club-logo">${c.league}</div><div><div class="club-hero-name">${esc(c.name)}</div><div class="club-meta">${c.league} · Shared across advisors and POCs</div></div></div>${clubOverview(c,ix,meetings)}<div class="club-tabs"><button class="club-tab ${clubTab==='history'?'active':''}" data-tab="history">Interaction history (${ix.length})</button><button class="club-tab ${clubTab==='meetings'?'active':''}" data-tab="meetings">Planned meetings (${meetings.length})</button><button class="club-tab ${clubTab==='followups'?'active':''}" data-tab="followups">Next steps (${fs.length})</button></div><div id="club-tab-body">${clubTab==='history'?`<div class="timeline">${ix.length?ix.map(i=>`<div class="timeline-item"><div class="timeline-dot"></div><div><div class="timeline-date">${fmt(i.date)} · ${contactMeta(i)} ${i.sample?'<span class="pill">Sample</span>':''}</div><div class="timeline-title">Interaction summary</div><div class="timeline-text">${esc(i.summary)}</div><div class="cap-list">${capsTags(i.capabilities,i.other)}</div>${i.followups.length?`<div class="timeline-text"><b>Next steps</b><br>${i.followups.map(f=>`• ${esc(f.description)} — ${esc(f.status)}, due ${fmt(f.due)} (${esc(who(f.owner))})`).join('<br>')}</div>`:''}</div></div>`).join(''):`<div class="empty"><div class="empty-icon">◉</div>No interactions for this club yet.</div>`}</div>`:clubTab==='meetings'?`<div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Participants & agenda</th><th>Owner</th><th>Actions</th></tr></thead><tbody>${meetings.length?meetings.map(m=>`<tr><td>${fmt(m.date)}</td><td><div class="cell-title">${esc(m.meetingType||'Meeting')} · ${esc(m.clubPoc||'Club/client POC TBD')}</div><div class="cell-sub">EXL POC: ${esc(m.exlPoc||'TBD')}${m.clubPocDesignation?' · '+esc(m.clubPocDesignation):''} · ${esc(m.agenda||'No agenda')}</div></td><td>${esc(who(m.owner))}</td><td>${meetingActions(m)}</td></tr>`).join(''):`<tr><td colspan="4"><div class="empty">No meetings planned.</div></td></tr>`}</tbody></table></div>`:`<div class="table-wrap"><table class="table"><thead><tr><th>Next step</th><th>Owner</th><th>Due</th><th>Status</th><th></th></tr></thead><tbody>${fs.length?fs.map(f=>`<tr><td><div class="cell-title">${esc(f.description)}</div></td><td>${esc(who(f.owner))}</td><td>${fmt(f.due)} ${f.due<dt()?'<span class="pill red">Overdue</span>':''}</td><td><span class="pill orange">Open</span></td><td>${followupCanEdit(f)?`<button class="action-link" data-follow-status="${f.id}" data-next="Done">Mark done</button>`:''}</td></tr>`).join(''):`<tr><td colspan="5"><div class="empty">No open next steps.</div></td></tr>`}</tbody></table></div>`}</div></div><div class="detail-columns"><section class="card"><div class="card-head"><div><div class="card-title">Recent activity</div><div class="card-sub">Newest conversations first</div></div></div><div class="card-body">${ix.slice(0,2).map(activityRow).join('')||'<div class="empty">No activity yet.</div>'}</div></section><section class="card"><div class="card-head"><div><div class="card-title">Next steps</div><div class="card-sub">Meetings and actions to keep moving</div></div></div><div class="card-body">${meetings.slice(0,2).map(meetingCard).join('')}${fs.slice(0,2).map(taskCard).join('')||(!meetings.length?'<div class="empty">Nothing upcoming.</div>':'')}</div></section></div>`}
function historyPreview(id){const c=clubBy(id);if(!c)return '';const history=visibleInteractions().filter(x=>x.clubId===id).sort((a,b)=>b.date.localeCompare(a.date));if(!history.length)return `<div class="note" style="margin:0 0 14px">No previous interactions for ${esc(c.name)} yet.</div>`;return `<div class="card" style="margin-bottom:14px"><div class="card-head"><div><div class="card-title">${esc(c.name)} · recent history</div><div class="card-sub">${history.length} previous ${history.length===1?'interaction':'interactions'} available while you prepare</div></div><button type="button" class="link-btn" data-open-club="${c.id}">Open club →</button></div><div class="card-body">${history.slice(0,2).map(x=>`<div class="activity-row"><div class="league-mark">${c.league}</div><div><div class="activity-club">${fmt(x.date)}</div><div class="activity-summary">${esc(x.summary)}</div><div class="cap-list">${capsTags(x.capabilities,x.other)}</div></div></div>`).join('')}</div></div>`}
function interactionForm(prefill=''){
 const clubs=visibleClubs().slice().sort((a,b)=>a.name.localeCompare(b.name)),i=editingInteraction,scheduled=meetingToComplete?db.meetings.find(m=>m.id===meetingToComplete):null,planned=null,cId=prefill||i?.clubId||scheduled?.clubId||'';
 const stakeholder=(i?.stakeholders||[])[0]||{},participant=(i?.participants||[])[0]||{};
 const clientName=i?.clubPoc||stakeholder.name||scheduled?.clubPoc||'',clientRole=i?.clubPocDesignation||stakeholder.role||scheduled?.clubPocDesignation||'';
 const exlName=i?.exlPoc||participant.name||scheduled?.exlPoc||user().name;
 const followups=i?.followups||[{description:'',owner:user().id,due:'',status:'Open'}];
 const clubOptions=clubs.map(c=>'<option value="'+c.id+'" '+(c.id===cId?'selected':'')+'>'+esc(c.name)+' · '+c.league+'</option>').join('');
 const capOptions=CAPS.map(c=>'<label class="check-option"><input type="checkbox" name="capability" value="'+esc(c)+'" '+((i?.capabilities||[]).includes(c)?'checked':'')+'>'+esc(c)+'</label>').join('');
 const nextOptions=NEXT_STEP_TYPES.map(x=>'<option '+((i?.nextStepType||'Yet to be decided')===x?'selected':'')+'>'+esc(x)+'</option>').join('');
 const isEdit=!!i||!!planned;
 return head(i?'EDIT INTERACTION':planned?'COMPLETE PLANNED MEETING':'CAPTURE THE CONVERSATION',i?'Update interaction':planned?'Complete planned meeting':'Log an interaction','Record a completed conversation or schedule a future meeting.', '<button class="btn" data-page="clubs">Cancel</button>')
 +'<div class="form-wrap"><div id="club-history-slot">'+historyPreview(cId)+'</div><form class="card form-card" id="interaction-form">'
 +'<div class="form-section"><h3 class="form-section-title">01 &nbsp; Meeting details</h3><div class="form-grid">'
 +(!isEdit?'<div class="field"><label>What are you recording? *</label><select class="select" name="recordMode" id="record-mode"><option value="interaction">Completed interaction</option><option value="planned">Plan a meeting</option></select></div>':'')
 +'<div class="field"><label>Club *</label><select class="select" name="clubId" required><option value="">Select a club</option>'+clubOptions+'</select></div><div class="field"><label id="date-label">'+(planned?'Meeting date *':'Interaction date *')+'</label><input class="input" name="date" type="date" value="'+(i?.date||scheduled?.date||dt())+'" required></div>'
 +'<div class="field" id="meeting-type-wrap" style="'+(planned?'':'display:none')+'"><label>Meeting type *</label><select class="select" name="meetingType" id="meeting-type"><option value="First meeting" '+((planned?.meetingType||'First meeting')==='First meeting'?'selected':'')+'>First meeting</option><option value="Follow-up meeting" '+(planned?.meetingType==='Follow-up meeting'?'selected':'')+'>Follow-up meeting</option></select></div>'
 +'<div class="field full"><label>EXL POC *</label><div id="participant-rows"><div class="attendee-row poc-single"><input class="mini-input" name="participantName" placeholder="EXL point of contact" value="'+esc(exlName)+'" required><input type="hidden" name="participantRole" value="EXL POC"></div></div></div>'
 +'<div class="field full"><label>Club/client POC *</label><div id="stakeholder-rows"><div class="attendee-row poc-pair"><input class="mini-input" name="stakeholderName" placeholder="Club/client point of contact" value="'+esc(clientName)+'" required><input class="mini-input" name="stakeholderRole" placeholder="Designation" value="'+esc(clientRole)+'" required></div></div></div>'
 +'<div class="field full"><label id="summary-label">'+(planned?'Meeting description / agenda *':'Discussion summary *')+'</label><textarea class="textarea" name="summary" required placeholder="'+(planned?'Describe the introductory meeting and what you plan to discuss.':'What did you discuss?')+'">'+esc(i?.summary||scheduled?.agenda||'')+'</textarea></div><div class="field full note" id="planned-hint" style="'+(planned?'':'display:none')+'">This saves an upcoming meeting only. It will not appear as a completed interaction until you mark it complete.</div></div></div>'
 +'<div id="completed-only-fields" style="'+(planned?'display:none':'')+'"><div class="form-section"><h3 class="form-section-title">02 &nbsp; Capabilities discussed</h3><div class="check-grid">'+capOptions+'</div><div class="field" id="other-field" style="margin-top:10px;'+((i?.capabilities||[]).includes('Other')?'':'display:none')+'"><label>What else was discussed?</label><input class="input" name="other" placeholder="Add a capability or topic" value="'+esc(i?.other||'')+'"></div></div>'
 +'<div class="form-section"><h3 class="form-section-title">03 &nbsp; Overall status and next meeting</h3><div class="form-grid"><div class="field"><label>Overall status *</label><select class="select" name="nextStepType" required>'+nextOptions+'</select></div><div class="field"><label>Next meeting date</label><input class="input" type="date" name="nextMeeting" value="'+(i?.nextMeeting||'')+'"></div><div class="field full"><label>Next meeting agenda (optional)</label><input class="input" name="nextAgenda" value="'+esc(i?.nextAgenda||'')+'" placeholder="Topic for the next conversation"></div></div><p class="hint">A meeting date creates a planned meeting, not a completed interaction.</p></div>'
 +'<div class="form-section"><h3 class="form-section-title">04 &nbsp; Next steps</h3><span class="hint">Add specific actions with an owner and due date.</span><div id="followup-rows" style="margin-top:10px">'+followups.map(f=>followRow(f)).join('')+'</div><button type="button" class="btn small" data-add-row="followup">＋ Add next step</button></div></div>'
 +'<div class="form-actions"><button type="button" class="btn" data-page="clubs">Cancel</button><button class="btn primary" type="submit">'+(i?'Save changes':planned?'Save interaction':'<span id="submit-label">Save interaction</span>')+' &nbsp; →</button></div></form></div>';
}
function syncInteractionMode(){const planned=$('#record-mode')?.value==='planned';const fields=$('#completed-only-fields'),type=$('#meeting-type-wrap'),date=$('[name=date]'),meetingType=$('#meeting-type'),summary=$('[name=summary]');if(fields){fields.style.display=planned?'none':'';fields.querySelectorAll('input,select,textarea,button').forEach(x=>x.disabled=planned)}if(type)type.style.display=planned?'grid':'none';if(date)date.previousElementSibling.textContent=planned?'Meeting date *':'Interaction date *';if(meetingType)meetingType.required=planned;if(summary){summary.previousElementSibling.textContent=planned?'Meeting description / agenda *':'Discussion summary *';summary.placeholder=planned?'Describe the introductory meeting and what you plan to discuss.':'What did you discuss?'}const hint=$('#planned-hint');if(hint)hint.style.display=planned?'block':'none';const submit=$('#submit-label');if(submit)submit.textContent=planned?'Save planned meeting':'Save interaction'}
function attendeeRow(a,kind){return `<div class="attendee-row"><input class="mini-input" name="${kind}Name" placeholder="Name" value="${esc(a.name)}"><input class="mini-input" name="${kind}Role" placeholder="Role" value="${esc(a.role)}"><button type="button" class="action-link" data-remove-row>×</button></div>`}
function followRow(f){return `<div class="follow-row"><input class="mini-input" name="followDescription" placeholder="Action description" value="${esc(f.description)}"><select class="mini-input" name="followOwner">${db.users.map(u=>`<option value="${u.id}" ${u.id===f.owner?'selected':''}>${esc(u.name)}</option>`).join('')}</select><input class="mini-input" type="date" name="followDue" value="${f.due||''}"><select class="mini-input" name="followStatus">${['Open','Done','Canceled'].map(s=>`<option ${f.status===s?'selected':''}>${s}</option>`).join('')}</select><button type="button" class="action-link" data-remove-row>×</button></div>`}
function meetingActions(m){if(!isAdmin()&&m.owner!==user().id)return '';return '<button class="action-link" data-meeting-edit="'+m.id+'">Edit</button>'+(isAdmin()?'':'<button class="action-link" data-meeting-complete="'+m.id+'">Complete</button>')+'<button class="action-link" data-meeting-cancel="'+m.id+'">Cancel</button>'}
function followupsPage(){const rows=allFollowups().filter(f=>f.status==='Open').sort((a,b)=>a.due.localeCompare(b.due));const over=rows.filter(f=>f.due<dt()).length;return `${head('NEXT STEPS','My next steps','Keep commitments visible and move each conversation forward.','<button class="btn" data-page="digest">◷ &nbsp; Overview</button>')}<div class="stats-grid" style="grid-template-columns:repeat(3,minmax(0,1fr))">${stat('Open next steps','Assigned to you',rows.filter(f=>f.owner===user().id||f.interaction.owner===user().id).length,'✓')}${stat('Overdue','Past their due date',over,'!')}${stat('Due this week','Next 7 days',rows.filter(f=>f.due>=dt()&&f.due<=dt(7)).length,'◷')}</div><div class="card"><div class="card-head"><div><div class="card-title">Next steps</div><div class="card-sub">Actions you own or can manage across clubs you can access</div></div><select class="select" id="follow-status-filter"><option value="Open">Open</option><option value="all">All statuses</option><option value="Done">Done</option><option value="Canceled">Canceled</option></select></div><div class="table-wrap"><table class="table"><thead><tr><th>Next step</th><th>Club</th><th>Owner</th><th>Due date</th><th>Status</th><th></th></tr></thead><tbody id="follow-table">${followRows(rows)}</tbody></table></div></div>`}
function followRows(rows){return rows.length?rows.map(f=>`<tr><td><div class="cell-title">${esc(f.description)}</div><div class="cell-sub">From ${fmt(f.interaction.date)} interaction</div></td><td><button class="action-link" data-open-club="${f.club?.id}">${esc(clubShort(f.club))}</button></td><td>${esc(who(f.owner))}</td><td>${fmt(f.due)} ${f.due<dt()&&f.status==='Open'?'<span class="pill red">Overdue</span>':''}</td><td><span class="pill ${f.status==='Open'?'orange':f.status==='Done'?'green':'red'}">${f.status}</span></td><td>${f.status==='Open'&&followupCanEdit(f)?`<button class="action-link" data-follow-status="${f.id}" data-next="Done">Mark done</button><button class="action-link" data-follow-status="${f.id}" data-next="Canceled">Cancel</button>`:''}</td></tr>`).join(''):`<tr><td colspan="6"><div class="empty"><div class="empty-icon">✓</div>No next steps in this view.</div></td></tr>`}
function followupCanEdit(f){return isAdmin()||f.owner===user().id||f.interaction.owner===user().id}
function digestPage(){
 const today=dt(),monthStart=new Date();monthStart.setDate(1);const start=monthStart.toISOString().slice(0,10);
 const ix=visibleInteractions();
 const from=$('#digest-from')?.value||start,to=$('#digest-to')?.value||today;
 const league=$('#digest-league')?.value||'all',club=$('#digest-club')?.value||'all',advisor=$('#digest-advisor')?.value||'all',poc=$('#digest-poc')?.value||'all',cap=$('#digest-cap')?.value||'all',status=$('#digest-status')?.value||'all',nextType=$('#digest-next-step')?.value||'all';
 const filtered=ix.filter(i=>{const c=clubBy(i.clubId);return i.date>=from&&i.date<=to&&(club==='all'||i.clubId===club)&&(league==='all'||c?.league===league)&&(advisor==='all'||i.participants.some(p=>p.role.toLowerCase().includes('advisor')&&p.name===who(advisor))||i.owner===advisor)&&(poc==='all'||i.participants.some(p=>p.role.toLowerCase().includes('poc')&&p.name===who(poc))||i.owner===poc)&&(cap==='all'||i.capabilities.includes(cap))&&(status==='all'||i.followups.some(f=>f.status===status))&&(nextType==='all'||(i.nextStepType||'Yet to be decided')===nextType)});
 const meetings=visibleMeetings().filter(m=>m.date>=today).sort((a,b)=>a.date.localeCompare(b.date));
 const dateField=(label,id,value)=>'<label class="filter-field"><span>'+label+'</span><input class="input" type="date" id="'+id+'" value="'+value+'"></label>';
 const selectField=(label,id,options,value)=>'<label class="filter-field"><span>'+label+'</span><select class="select" id="'+id+'">'+options.map(o=>'<option value="'+esc(o.value)+'" '+(o.value===value?'selected':'')+'>'+esc(o.label)+'</option>').join('')+'</select></label>';
 const leagueOptions=[{value:'all',label:'All leagues'},...Object.keys(LEAGUES).map(x=>({value:x,label:x}))];
 const clubOptions=[{value:'all',label:'All clubs'},...visibleClubs().map(c=>({value:c.id,label:c.name}))];
 const userOptions=[{value:'all',label:'All users'},...db.users.filter(u=>u.role==='User').map(u=>({value:u.id,label:u.name}))];
 const capOptions=[{value:'all',label:'All capabilities'},...CAPS.map(x=>({value:x,label:x}))];
 const statusOptions=[{value:'all',label:'All next-step statuses'},...['Open','Done','Canceled'].map(x=>({value:x,label:x}))];
 const nextOptions=[{value:'all',label:'All next-step tags'},...NEXT_STEP_TYPES.map(x=>({value:x,label:x}))];
 const actions='<button class="btn" id="clear-digest">Reset filters</button>'+(isAdmin()?'':'<button class="btn primary" data-page="log">＋ &nbsp; Log interaction</button>');
 const groups=isAdmin()?'<div class="segmented"><button class="active" type="button">All users</button><button data-group="advisor">By advisor</button><button data-group="poc">By EXL POC</button></div>':'';
 activeDigestItems=filtered;
 return head('RELATIONSHIP ACTIVITY','Overview','Completed conversations, upcoming meetings, and follow-through in one place.',actions)
 +'<section class="card upcoming-top"><div class="card-head"><div><div class="card-title">Upcoming meetings</div><div class="card-sub">Your next scheduled conversations</div></div><span class="count-badge">'+meetings.length+'</span></div><div class="upcoming-strip">'+(meetings.length?meetings.slice(0,4).map(meetingCard).join(''):'<div class="empty">No upcoming meetings are scheduled.</div>')+'</div></section>'
 +'<section class="card filter-panel"><div class="filter-panel-title"><div><div class="card-title">Activity filters</div><div class="card-sub">Choose a date range and narrow the activity below</div></div><span class="filter-panel-icon">⌕</span></div><div class="digest-controls">'
 +dateField('From date','digest-from',from)+dateField('To date','digest-to',to)
 +selectField('League','digest-league',leagueOptions,league)+selectField('Club','digest-club',clubOptions,club)
 +selectField('Advisor','digest-advisor',userOptions,advisor)+selectField('EXL POC','digest-poc',userOptions,poc)
 +selectField('Capability','digest-cap',capOptions,cap)+selectField('Action status','digest-status',statusOptions,status)+selectField('Overall status','digest-next-step',nextOptions,nextType)
 +'</div></section>'
 +'<section class="overview-section"><div class="overview-section-heading"><div><div class="greeting">ACTIVITY SNAPSHOT</div><h2>Overview</h2><p>'+esc(fmt(from,{month:'short',day:'numeric',year:'numeric'}))+' – '+esc(fmt(to,{month:'short',day:'numeric',year:'numeric'}))+'</p></div></div>'
 +'<div class="stats-grid overview-stat-grid">'+stat('Completed interactions','In selected date range',filtered.length,'◉')+stat('Unique clubs','With interactions',new Set(filtered.map(i=>i.clubId)).size,'▦')+stat('Upcoming meetings','Planned from today',meetings.length,'◷')+'</div>'
 +'<section class="card"><div class="card-head"><div><div class="card-title">Interaction activity</div><div class="card-sub">Club/client and EXL points of contact, discussion, overall status, and next steps</div></div>'+groups+'</div><div class="digest-list" id="digest-results">'+digestRows(filtered)+'</div></section></section>'+overviewSupport();
}
function overviewSupport(){const tasks=allFollowups().filter(f=>f.status==='Open').sort((a,b)=>a.due.localeCompare(b.due)).slice(0,4);return '<div class="overview-support"><section class="card"><div class="card-head"><div><div class="card-title">Next steps</div><div class="card-sub">Specific actions, sorted by due date</div></div><button class="link-btn" data-page="followups">All next steps →</button></div><div class="card-body">'+(tasks.length?tasks.map(taskCard).join(''):'<div class="empty">No open next steps.</div>')+'</div></section></div>'}
function digestRows(ix){
 if(!ix.length)return '<div class="empty"><div class="empty-icon">◷</div>No interactions match these filters.</div>';
 return ix.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(i=>{
  const c=clubBy(i.clubId),steps=i.followups||[];
  const stepRows=steps.length?steps.map(f=>{
   const overdue=f.status==='Open'&&f.due<dt();
   const state=overdue?'<span class="pill red">Overdue</span>':'<span class="pill '+(f.status==='Done'?'green':f.status==='Canceled'?'red':'orange')+'">'+esc(f.status)+'</span>';
   return '<div class="next-action-row"><div class="next-action-copy"><div class="next-action-title">'+esc(f.description)+'</div><div class="next-action-meta">Owner: '+esc(who(f.owner))+' <span>·</span> Due: '+fmt(f.due)+'</div></div>'+state+'</div>';
  }).join(''):'<div class="next-action-empty">No individual actions recorded.</div>';
  return '<article class="digest-item interaction-record">'
   +'<header class="interaction-record-head"><div class="interaction-record-club"><div class="league-mark">'+(c?.league||'—')+'</div><div><div class="activity-club">'+esc(clubShort(c))+' '+leagueTag(c?.league||'')+(i.sample?' <span class="pill sample-pill">Sample</span>':'')+'</div><div class="activity-meta">'+fmt(i.date)+'</div></div></div><button class="action-link" data-open-club="'+i.clubId+'">Club history →</button></header>'
   +'<div class="interaction-pocs"><div class="interaction-poc"><span class="poc-label">EXL POC</span><strong>'+esc(exlPoc(i))+'</strong></div><div class="poc-divider"></div><div class="interaction-poc"><span class="poc-label">Club/client POC</span><strong>'+esc(clubPoc(i))+'</strong><span class="poc-designation">'+esc(clubPocDesignation(i))+'</span></div></div>'
   +'<div class="interaction-record-body"><section class="interaction-discussion"><div class="interaction-section-label"><span class="section-icon">◌</span>Discussion summary</div><p>'+esc(i.summary)+'</p><div class="interaction-section-label capability-heading">Solutions discussed</div><div class="cap-list">'+capsTags(i.capabilities,i.other)+'</div></section>'
   +'<aside class="interaction-next-panel"><div class="interaction-next-head"><div><div class="next-kicker">ACTION PLAN</div><h3>Next steps</h3></div><div class="overall-status"><span>Overall status</span>'+nextStepPill(i)+'</div></div><div class="next-action-list">'+stepRows+'</div></aside></div></article>';
 }).join('');
}
function adminPage(){if(!isAdmin()){page='home';return homePage()}return `${head('WORKSPACE ADMIN','Workspace users','Every advisor and EXL POC can work with any club. Interaction and next-step editing follows record ownership.','')}<div class="admin-grid"><section class="card"><div class="card-head"><div><div class="card-title">Shared club directory</div><div class="card-sub">All clubs are available to all advisors and EXL POCs.</div></div></div><div class="card-body"><div class="note">Anyone on the team can log a meeting with any NFL, MLB, MLS, NHL, or NBA club and see its shared interaction history.</div></div></section><section class="card"><div class="card-head"><div><div class="card-title">Workspace users</div><div class="card-sub">Demo accounts and their workspace roles</div></div></div><div class="card-body">${db.users.map(u=>`<div class="admin-user"><div><div class="cell-title">${esc(u.name)}</div><div class="cell-sub">${esc(u.title)}</div></div><span class="pill ${u.role==='Admin'?'blue':'green'}">${u.role}</span></div>`).join('')}<div class="note" style="margin-top:14px">Regular users can create interactions and meetings for any club, and manage their own records. Admins can review and manage all activity.</div></div></section></div>`}
function bindPage(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;editingInteraction=null;app()});document.querySelectorAll('[data-open-club]').forEach(b=>b.onclick=()=>{selectedClub=b.dataset.openClub;clubTab='history';page='club';app()});document.querySelectorAll('[data-log-club]').forEach(b=>b.onclick=()=>{editingInteraction=null;page='log';app();const s=document.querySelector('[name=clubId]');if(s){s.value=b.dataset.logClub;s.dispatchEvent(new Event('change'))}});
 const cs=$('#club-search'),lf=$('#league-filter');if(cs||lf){const filter=()=>{const term=(cs?.value||'').toLowerCase(),league=lf?.value||'all';$('#club-results').innerHTML=clubCards(visibleClubs().filter(c=>c.name.toLowerCase().includes(term)&&(league==='all'||c.league===league)))};cs?.addEventListener('input',filter);lf?.addEventListener('change',filter)}
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{clubTab=b.dataset.tab;renderPage()});
 document.querySelectorAll('[data-add-row]').forEach(b=>b.onclick=()=>{const kind=b.dataset.addRow,holder=$(`#${kind==='followup'?'followup-rows':kind==='stakeholder'?'stakeholder-rows':'participant-rows'}`);holder.insertAdjacentHTML('beforeend',kind==='followup'?followRow({description:'',owner:user().id,due:'',status:'Open'}):attendeeRow({name:'',role:''},kind))});document.querySelectorAll('[data-remove-row]').forEach(b=>b.onclick=()=>{const row=b.parentElement;const parent=row.parentElement;if(parent.children.length>1)row.remove();else row.querySelectorAll('input').forEach(i=>i.value='')});
 document.querySelectorAll('[name=capability]').forEach(x=>x.onchange=()=>{$('#other-field').style.display=document.querySelector('[name=capability][value="Other"]').checked?'grid':'none'});
 if($('#interaction-form')){$('#interaction-form').onsubmit=saveInteraction;const mode=$('#record-mode');mode?.addEventListener('change',()=>syncInteractionMode());syncInteractionMode()}document.querySelector('[name=clubId]')?.addEventListener('change',e=>{$('#club-history-slot').innerHTML=historyPreview(e.target.value)});
 document.querySelectorAll('[data-follow-status]').forEach(b=>b.onclick=()=>changeFollowup(b.dataset.followStatus,b.dataset.next));
 $('#follow-status-filter')?.addEventListener('change',e=>{const x=allFollowups().filter(f=>e.target.value==='all'||f.status===e.target.value).sort((a,b)=>a.due.localeCompare(b.due));$('#follow-table').innerHTML=followRows(x)});
 ['digest-from','digest-to','digest-club','digest-league','digest-advisor','digest-poc','digest-cap','digest-status','digest-next-step'].forEach(id=>$('#'+id)?.addEventListener('change',()=>{const oldPage=page;renderPage();}));
 $('#clear-digest')?.addEventListener('click',()=>{document.querySelectorAll('.digest-controls select').forEach(x=>x.value='all');$('#digest-from').value=new Date(new Date().getFullYear(),new Date().getMonth(),1).toISOString().slice(0,10);$('#digest-to').value=dt();page='home';app()});
 document.querySelectorAll('[data-meeting-edit]').forEach(b=>b.onclick=()=>meetingModal(b.dataset.meetingEdit));document.querySelectorAll('[data-meeting-cancel]').forEach(b=>b.onclick=()=>cancelMeeting(b.dataset.meetingCancel));document.querySelectorAll('[data-meeting-complete]').forEach(b=>b.onclick=()=>completeMeeting(b.dataset.meetingComplete));

 document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-group]').forEach(x=>x.classList.toggle('active',x===b));const typ=b.dataset.group;const x=$('#digest-results');if(typ==='advisor'){const groups={};activeDigestItems.forEach(i=>(i.participants.filter(p=>p.role.toLowerCase().includes('advisor')).map(p=>p.name).join(', ')||who(i.owner)).split(', ').forEach(n=>(groups[n]??=[]).push(i)));x.innerHTML=Object.entries(groups).map(([n,arr])=>`<div class="digest-item"><div class="activity-club">${esc(n)} <span class="pill">${arr.length} interactions</span></div>${digestRows(arr)}</div>`).join('')||'<div class="empty">No activity to group.</div>'}else{const groups={};activeDigestItems.forEach(i=>i.participants.filter(p=>p.role.toLowerCase().includes('poc')).forEach(p=>(groups[p.name]??=[]).push(i)));x.innerHTML=Object.entries(groups).map(([n,arr])=>`<div class="digest-item"><div class="activity-club">${esc(n)} <span class="pill">${arr.length} interactions</span></div>${digestRows(arr)}</div>`).join('')||'<div class="empty">No POC activity to group.</div>'}})
}
function collectRows(form,kind){return [...form.querySelectorAll(`.${kind==='follow'?'follow-row':'attendee-row'}`)]}
function saveInteraction(e){
 e.preventDefault();if(isAdmin()&&!editingInteraction){toast('The Admin account reviews existing activity. Sign in as an EXL user to log an interaction.');return}
 const form=e.target,fd=new FormData(form),clubId=fd.get('clubId');if(!canSeeClub(clubId)){toast('You do not have access to that club');return}
 const attendees=kind=>collectRows(form,kind).map(r=>({name:r.querySelector('[name='+kind+'Name]')?.value.trim()||'',role:r.querySelector('[name='+kind+'Role]')?.value.trim()||''})).filter(a=>a.name);
 const stakeholders=attendees('stakeholder'),participants=attendees('participant');
 if(fd.get('recordMode')==='planned'){
  const date=fd.get('date');if(date<dt()){toast('Choose today or a future date for a planned meeting');return}
  const meeting={id:'m-'+Date.now(),clubId,date,meetingType:fd.get('meetingType')||'First meeting',exlPoc:participants[0]?.name||'',clubPoc:stakeholders[0]?.name||'',clubPocDesignation:stakeholders[0]?.role||'',participants:[stakeholders[0]?.name,participants[0]?.name].filter(Boolean),agenda:fd.get('summary').trim(),owner:user().id,status:'Planned'};
  db.meetings.push(meeting);save();editingInteraction=null;meetingToComplete=null;page='club';selectedClub=clubId;clubTab='meetings';app();toast('Planned meeting saved. It is not counted as a completed interaction.');return;
 }
 const followups=collectRows(form,'follow').map(r=>({id:r.dataset.id||'f-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),description:r.querySelector('[name=followDescription]').value.trim(),owner:r.querySelector('[name=followOwner]').value,due:r.querySelector('[name=followDue]').value,status:r.querySelector('[name=followStatus]').value})).filter(f=>f.description);if(followups.some(f=>!f.due)){toast('Add a due date for each next step');return}
 const prev=editingInteraction,nextDate=fd.get('nextMeeting');const record={id:prev?.id||'i-'+Date.now(),clubId,date:fd.get('date'),stakeholders,participants,exlPoc:participants[0]?.name||'',clubPoc:stakeholders[0]?.name||'',clubPocDesignation:stakeholders[0]?.role||'',nextStepType:fd.get('nextStepType')||'Yet to be decided',summary:fd.get('summary').trim(),capabilities:fd.getAll('capability'),other:fd.get('other')?.trim()||'',owner:prev?.owner||user().id,sample:false,followups,nextMeeting:nextDate||'',nextAgenda:fd.get('nextAgenda')?.trim()||''};if(prev)db.interactions=db.interactions.map(x=>x.id===prev.id?record:x);else db.interactions.push(record);
 let linked=prev?.meetingId&&db.meetings.find(m=>m.id===prev.meetingId);if(meetingToComplete){linked=db.meetings.find(m=>m.id===meetingToComplete);if(linked){linked.status='Completed';record.meetingId=linked.id}meetingToComplete=null}else if(nextDate){if(linked){linked.date=nextDate;linked.agenda=record.nextAgenda}else{linked={id:'m-'+Date.now(),clubId,date:nextDate,meetingType:'Follow-up meeting',exlPoc:record.exlPoc,clubPoc:record.clubPoc,clubPocDesignation:record.clubPocDesignation,participants:stakeholders.map(a=>a.name).concat(participants.map(a=>a.name)),agenda:record.nextAgenda,owner:user().id,status:'Planned'};db.meetings.push(linked)}record.meetingId=linked.id}else if(linked&&linked.status==='Planned'){linked.status='Canceled'}
 save();editingInteraction=null;page='club';selectedClub=clubId;clubTab='history';app();toast(prev?'Interaction updated':'Interaction saved')
}
function changeFollowup(id,status){let found;db.interactions.forEach(i=>i.followups.forEach(f=>{if(f.id===id)found={i,f}}));if(!found||(!isAdmin()&&found.f.owner!==user().id&&found.i.owner!==user().id)){toast('You do not have access to update this action');return}found.f.status=status;save();renderPage();toast(`Next step marked ${status.toLowerCase()}`)}
function meetingModal(id=''){
 const m=db.meetings.find(x=>x.id===id);if(m&&!isAdmin()&&m.owner!==user().id)return;
 const content=`<div class="modal-backdrop" id="modal-backdrop"><div class="modal"><div class="modal-head"><div class="modal-title">${m?'Edit planned meeting':'Plan a meeting'}</div><button class="close" data-close>×</button></div><form class="modal-body" id="meeting-form"><div class="form-grid"><div class="field"><label>Club *</label><select class="select" name="clubId" required>${visibleClubs().map(c=>`<option value="${c.id}" ${c.id===(m?.clubId||selectedClub)?'selected':''}>${esc(c.name)} · ${c.league}</option>`).join('')}</select></div><div class="field"><label>Meeting date *</label><input class="input" type="date" name="date" value="${m?.date||''}" required></div><div class="field"><label>Meeting type *</label><select class="select" name="meetingType"><option ${m?.meetingType==='First meeting'?'selected':''}>First meeting</option><option ${m?.meetingType==='Follow-up meeting'?'selected':''}>Follow-up meeting</option></select></div><div class="field"><label>EXL POC *</label><input class="input" name="exlPoc" value="${esc(m?.exlPoc||user().name)}" required></div><div class="field"><label>Club/client POC *</label><input class="input" name="clubPoc" value="${esc(m?.clubPoc||'')}" required></div><div class="field"><label>Designation *</label><input class="input" name="clubPocDesignation" value="${esc(m?.clubPocDesignation||'')}" required></div><div class="field full"><label>Meeting description / agenda</label><textarea class="textarea" name="agenda" placeholder="What do you plan to discuss?">${esc(m?.agenda||'')}</textarea></div></div><div class="form-actions"><button type="button" class="btn" data-close>Cancel</button><button class="btn primary">Save meeting</button></div></form></div></div>`;
 document.body.insertAdjacentHTML('beforeend',content);$('#modal-backdrop').onclick=e=>{if(e.target.id==='modal-backdrop'||e.target.closest('[data-close]'))$('#modal-backdrop').remove()};
 $('#meeting-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target),clubId=d.get('clubId');if(!canSeeClub(clubId)){toast('You do not have access to that club');return}const record={id:m?.id||`m-${Date.now()}`,clubId,date:d.get('date'),meetingType:d.get('meetingType'),exlPoc:d.get('exlPoc').trim(),clubPoc:d.get('clubPoc').trim(),clubPocDesignation:d.get('clubPocDesignation').trim(),participants:[d.get('clubPoc').trim(),d.get('exlPoc').trim()],agenda:d.get('agenda').trim(),owner:m?.owner||user().id,status:'Planned'};if(m)db.meetings=db.meetings.map(x=>x.id===m.id?record:x);else db.meetings.push(record);save();$('#modal-backdrop').remove();renderPage();toast(m?'Meeting updated':'Meeting planned')}
}
function cancelMeeting(id){const m=db.meetings.find(x=>x.id===id);if(!m||(!isAdmin()&&m.owner!==user().id))return;if(confirm('Cancel this planned meeting?')){m.status='Canceled';save();renderPage();toast('Meeting canceled')}}
function completeMeeting(id){const m=db.meetings.find(x=>x.id===id);if(!m||isAdmin()||m.owner!==user().id)return;meetingToComplete=id;editingInteraction=null;page='log';app();const s=document.querySelector('[name=clubId]'),d=document.querySelector('[name=date]');if(s){s.value=m.clubId;s.dispatchEvent(new Event('change'))}if(d)d.value=m.date;toast('Add the POC details and discussion notes to complete this meeting')}
// Keep next step identifiers stable when an interaction is edited.
function followRow(f){return `<div class="follow-row" data-id="${esc(f.id||'')}"><input class="mini-input" name="followDescription" placeholder="Action description" value="${esc(f.description)}"><select class="mini-input" name="followOwner">${db.users.map(u=>`<option value="${u.id}" ${u.id===f.owner?'selected':''}>${esc(u.name)}</option>`).join('')}</select><input class="mini-input" type="date" name="followDue" value="${f.due||''}"><select class="mini-input" name="followStatus">${['Open','Done','Canceled'].map(s=>`<option ${f.status===s?'selected':''}>${s}</option>`).join('')}</select><button type="button" class="action-link" data-remove-row>×</button></div>`}
// Defer completing a planned meeting until its interaction notes are saved.
function completeMeeting(id){const m=db.meetings.find(x=>x.id===id);if(!m||isAdmin()||m.owner!==user().id)return;meetingToComplete=id;editingInteraction=null;page='log';app();const s=document.querySelector('[name=clubId]'),d=document.querySelector('[name=date]');if(s){s.value=m.clubId;s.dispatchEvent(new Event('change'))}if(d)d.value=m.date;toast('Add the POC details and discussion notes to complete this meeting')}
