function loginPage(message=''){document.getElementById('app').innerHTML=`<main class="login-screen"><section class="login-card"><div class="brand login-brand"><div class="brand-mark">C</div><div><div class="brand-name">clubhouse</div><div class="brand-sub">Relationship activity</div></div></div><div class="login-intro"><div class="greeting">SPORTS PARTNERSHIPS</div><h1>Welcome back</h1><p>Sign in to review club conversations and keep the next steps moving.</p></div><form id="login-form" class="login-form"><label>Username<input class="input" name="username" autocomplete="username" placeholder="Enter your username" required></label><label>Password<input class="input" name="password" type="password" autocomplete="current-password" placeholder="Enter your password" required></label><div class="login-error" id="login-error">${esc(message)}</div><button class="btn primary login-submit" type="submit">Sign in <span>→</span></button></form><div class="demo-access"><div class="demo-access-title">Demo sign-ins</div><p>Choose an account to fill the sign-in form.</p><div class="demo-account-grid">${[['admin','Admin','ClubhouseAdmin26!'],['avery','Advisor','AveryClub26!'],['jamie','Advisor','JamieClub26!'],['taylor','Internal POC','TaylorClub26!']].map(([u,r,p])=>`<button type="button" class="demo-account" data-fill-login="${u}" data-password="${p}"><span>${esc(r)}</span><b>${esc(u)}</b></button>`).join('')}</div><div class="login-footnote">Local demo accounts · Use the Admin account first to initialize sample activity.</div></div></section><div class="login-aside"><div class="login-aside-mark">C</div><div class="login-aside-copy"><span>BUILT AROUND THE RELATIONSHIP</span><h2>Better conversations<br>start with a clear view.</h2><p>One place for club history, upcoming meetings, and the commitments that follow.</p></div><div class="login-aside-footer">NFL &nbsp; MLB &nbsp; MLS &nbsp; NHL &nbsp; NBA</div></div></main>`;document.querySelectorAll('[data-fill-login]').forEach(b=>b.onclick=()=>{$('[name=username]').value=b.dataset.fillLogin;$('[name=password]').value=b.dataset.password;$('#login-error').textContent=''});$('#login-form').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),button=e.target.querySelector('button[type=submit]');button.disabled=true;button.textContent='Signing in…';try{const r=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:fd.get('username'),password:fd.get('password')})});const payload=await r.json();if(!r.ok)throw new Error(payload.error||'Sign in failed');if(payload.state)db=payload.state;else if(payload.actor==='u-admin'){db=freshDB();db.activeUser=payload.actor;save()}else{loginPage('The admin account needs to sign in once to initialize this workspace.');return}page='home';app()}catch(err){$('#login-error').textContent=err.message;button.disabled=false;button.innerHTML='Sign in <span>→</span>'}}}
async function init(){try{const r=await fetch('/api/session');const payload=await r.json();if(!payload.authenticated){loginPage();return}if(payload.state)db=payload.state;else if(payload.actor==='u-admin'){db=freshDB();db.activeUser=payload.actor;save()}else{loginPage('Ask an admin to initialize the workspace before signing in as a regular user.');return}app()}catch(e){loginPage('Start the local server with python3 server.py, then reload this page.')}};init();
